#pragma once

namespace interface {
	struct Server;
}

namespace server
{
	// [WEB_LOCAL_SERVER]: a server with its modules linked in, not compiled
	// and loaded at its start. The table is generated by
	// util/web_server.cmake and ends in a row of nulls.
	struct StaticModule {
		const char *name;
		void* (*create)(interface::Server *server);
	};
	extern const StaticModule g_static_modules[];
}
